'use strict';
const $ = (q) => document.querySelector(q);
const esc = (s = '') => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels = {overview:'Overview',systems:'Your systems',findings:'Needs review',impact:'Impact',sources:'Watched sources',history:'Check history',guide:'Using BuiltWatch',admin:'Owner dashboard'};
